/**
 * @name Path traversal vulnerability in file operations
 * @description File paths derived from external sources without validation can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters that could be controlled by external input
    exists(DataFlow::ParameterNode param |
      source = param and
      (
        param.getParameter().getName().matches(["%key%", "%filename%", "%path%", "%name%"]) or
        param.getParameter().getName() = ["bucket", "extra_args", "callback"]
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access operations
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from untrusted input $@.", source.getNode(), "user-controlled parameter"

/**
 * @name Command injection via subprocess
 * @description Using subprocess with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode or
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from $@.", source.getNode(), "user-controlled parameter"

/**
 * @name Unvalidated URL construction
 * @description Constructing URLs from untrusted input without validation can lead to security issues
 * @kind path-problem
 * @problem.severity warning
 * @id py/url-manipulation
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UrlManipulationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall() or
        call = API::moduleImport("requests").getMember(["get", "post", "put", "delete"]).getACall() or
        call = API::moduleImport("urllib").getMember("parse").getMember("urljoin").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module UrlManipulationFlow = TaintTracking::Global<UrlManipulationConfig>;
import UrlManipulationFlow::PathGraph

from UrlManipulationFlow::PathNode source, UrlManipulationFlow::PathNode sink
where UrlManipulationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "URL constructed from $@.", source.getNode(), "user input"

/**
 * @name SQL Injection
 * @description Using untrusted input in SQL queries can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(SqlExecution sql).getSql()
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SQL injection from $@.", source.getNode(), "user input"
